const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Find the Dry Chaco ecoregion from the WWF dataset.
  const ecoregions = ee.FeatureCollection('WWF/Terrestrial_Ecoregions');
  const dryChaco = ecoregions.filter(ee.Filter.eq('ECO_NAME', 'Dry Chaco')).geometry();

  // Check if the geometry was found.
  if (dryChaco.isEmpty().getInfo()) {
      console.log("Could not find the 'Dry Chaco' ecoregion geometry.");
      console.log('D');
      return;
  }

  // 2. Data Acquisition & Check
  // Use Hansen Global Forest Change dataset. A single image covers the whole period.
  const hansen = ee.Image('UMD/hansen/global_forest_change_2020_v1_8');

  // 3. Processing
  // Define forest as pixels with tree cover >= 30% in 2000.
  const treeCover = hansen.select(['treecover2000']);
  const forest2000 = treeCover.gte(30);

  // Identify areas that were forest in 2000 and were lost by 2019.
  const loss = hansen.select(['loss']);
  const lossYear = hansen.select(['lossyear']);
  // Loss years are coded 1-20 for 2001-2020. We need loss up to year 2019.
  const forestLoss2001_2019 = loss.and(lossYear.gte(1)).and(lossYear.lte(19));

  // Combine with the initial forest mask to get the area of forest lost.
  const actualForestLoss = forest2000.and(forestLoss2001_2019);

  // Create an image representing the area of each pixel in square kilometers.
  const areaImage = ee.Image.pixelArea().divide(1000000); // Convert sq meters to sq km

  // Calculate the total area for each class.
  const forestArea2000Image = forest2000.multiply(areaImage);
  const forestLossAreaImage = actualForestLoss.multiply(areaImage);

  const scale = 3000; // Use a coarse scale to avoid timeout.

  // 4. Calculation
  const stats2000 = forestArea2000Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dryChaco,
    scale: scale,
    maxPixels: 1e10
  });

  const statsLoss = forestLossAreaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dryChaco,
    scale: scale,
    maxPixels: 1e10
  });

  // Retrieve results asynchronously.
  const forestArea2000 = ee.Number(stats2000.get('treecover2000')).getInfo();
  const lossArea = ee.Number(statsLoss.get('treecover2000')).getInfo();

  // 5. Validation & Final Answer
  if (forestArea2000 === null || lossArea === null) {
      console.log("Calculation failed: Could not compute area values.");
      console.log('C3');
      return;
  }

  if (forestArea2000 === 0) {
      console.log("No forest cover found in the region for the year 2000.");
      console.log('C2');
      return;
  }

  const percentageLoss = (lossArea / forestArea2000) * 100;

  console.log(`Initial Forest Area (2000): ${forestArea2000.toFixed(0)} sq km`);
  console.log(`Forest Area Lost (2001-2019): ${lossArea.toFixed(0)} sq km`);
  console.log(`Percentage Loss: ${percentageLoss.toFixed(2)}%`);

  if (percentageLoss > 10) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
